StgParamValue StgParamValue::parse(const uint8_t* buf, size_t len, size_t& offset) {
    StgParamValue result;
    if (offset + 4 > len) throw std::runtime_error("buffer overflow");
    std::memcpy(&result.type_tag, buf + offset, 4);
    offset += 4;
    if (result.type_tag == 0) {
        auto& _val = result.value.emplace<0>();
        if (offset + 4 > len) throw std::runtime_error("buffer overflow");
        std::memcpy(&_val, buf + offset, 4);
        offset += 4;
    } else if (result.type_tag == 1) {
        auto& _val = result.value.emplace<1>();
        if (offset + 4 > len) throw std::runtime_error("buffer overflow");
        std::memcpy(&_val, buf + offset, 4);
        offset += 4;
    } else if (result.type_tag == 2) {
        result.value.emplace<2>(StgStringParam::parse(buf, len, offset));
    } else if (result.type_tag == 3) {
        auto& _val = result.value.emplace<0>();
        if (offset + 4 > len) throw std::runtime_error("buffer overflow");
        std::memcpy(&_val, buf + offset, 4);
        offset += 4;
    } else {
        throw std::runtime_error("unknown tag value for StgParamValue.value");
    }
    return result;
}

std::string StgParamValue::to_json() const {
    std::string s = "{";
    s += "\"type_tag\":";
    s += std::to_string(type_tag);
    s += ",";
    s += "\"value\":";
    if (value.index() == 0) {
        s += std::to_string(std::get<0>(value));
    } else if (value.index() == 1) {
        s += std::to_string(std::get<1>(value));
    } else if (value.index() == 2) {
        s += std::get<2>(value).to_json();
    } else if (value.index() == 0) {
        s += std::to_string(std::get<0>(value));
    }
    s += "}";
    return s;
}

std::vector<uint8_t> StgParamValue::to_bytes() const {
    std::vector<uint8_t> _buf;
    {
        uint32_t _tmp = type_tag;
        uint8_t _raw[4];
        std::memcpy(_raw, &_tmp, 4);
        _buf.insert(_buf.end(), _raw, _raw + 4);
    }
    if (value.index() == 0) {
        auto& _v = std::get<0>(value);
        int32_t _tmp = _v;
        uint8_t _raw[4];
        std::memcpy(_raw, &_tmp, 4);
        _buf.insert(_buf.end(), _raw, _raw + 4);
    } else if (value.index() == 1) {
        auto& _v = std::get<1>(value);
        float _tmp = _v;
        uint8_t _raw[4];
        std::memcpy(_raw, &_tmp, 4);
        _buf.insert(_buf.end(), _raw, _raw + 4);
    } else if (value.index() == 2) {
        auto _tmp = std::get<2>(value).to_bytes();
        _buf.insert(_buf.end(), _tmp.begin(), _tmp.end());
    } else if (value.index() == 0) {
        auto& _v = std::get<0>(value);
        int32_t _tmp = _v;
        uint8_t _raw[4];
        std::memcpy(_raw, &_tmp, 4);
        _buf.insert(_buf.end(), _raw, _raw + 4);
    }
    return _buf;
}

