File File::parse(const uint8_t* buf, size_t len, size_t& offset) {
    File result;
    if (offset + 4 > len) throw std::runtime_error("buffer overflow");
    std::memcpy(&result.magic, buf + offset, 4);
    offset += 4;
    if (!((result.magic == 1001))) {
        throw std::runtime_error("STG magic must be 0x3E9");
    }
    result.header = StgHeader::parse(buf, len, offset);
    if (offset + 4 > len) throw std::runtime_error("buffer overflow");
    std::memcpy(&result.unit_count, buf + offset, 4);
    offset += 4;
    for (size_t i = 0; i < result.unit_count; ++i) {
        result.units.push_back(UnitBlock::parse(buf, len, offset));
    }
    if (offset + 4 > len) throw std::runtime_error("buffer overflow");
    std::memcpy(&result.area_count, buf + offset, 4);
    offset += 4;
    for (size_t i = 0; i < result.area_count; ++i) {
        result.areas.push_back(AreaEntry::parse(buf, len, offset));
    }
    if (offset + 4 > len) throw std::runtime_error("buffer overflow");
    std::memcpy(&result.variable_count, buf + offset, 4);
    offset += 4;
    for (size_t i = 0; i < result.variable_count; ++i) {
        result.variables.push_back(StgVariable::parse(buf, len, offset));
    }
    if (offset + 4 > len) throw std::runtime_error("buffer overflow");
    std::memcpy(&result.event_block_count, buf + offset, 4);
    offset += 4;
    for (size_t i = 0; i < result.event_block_count; ++i) {
        result.event_blocks.push_back(EventBlock::parse(buf, len, offset));
    }
    if (offset + 4 > len) throw std::runtime_error("buffer overflow");
    std::memcpy(&result.footer_count, buf + offset, 4);
    offset += 4;
    for (size_t i = 0; i < result.footer_count; ++i) {
        result.footer_entries.push_back(FooterEntry::parse(buf, len, offset));
    }
    return result;
}

std::string File::to_json() const {
    std::string s = "{";
    s += "\"magic\":";
    s += std::to_string(magic);
    s += ",";
    s += "\"header\":";
    s += header.to_json();
    s += ",";
    s += "\"unit_count\":";
    s += std::to_string(unit_count);
    s += ",";
    s += "\"units\":";
    s += "[";
    for (size_t i = 0; i < units.size(); ++i) {
        if (i > 0) s += ",";
        s += units[i].to_json();
    }
    s += "]";
    s += ",";
    s += "\"area_count\":";
    s += std::to_string(area_count);
    s += ",";
    s += "\"areas\":";
    s += "[";
    for (size_t i = 0; i < areas.size(); ++i) {
        if (i > 0) s += ",";
        s += areas[i].to_json();
    }
    s += "]";
    s += ",";
    s += "\"variable_count\":";
    s += std::to_string(variable_count);
    s += ",";
    s += "\"variables\":";
    s += "[";
    for (size_t i = 0; i < variables.size(); ++i) {
        if (i > 0) s += ",";
        s += variables[i].to_json();
    }
    s += "]";
    s += ",";
    s += "\"event_block_count\":";
    s += std::to_string(event_block_count);
    s += ",";
    s += "\"event_blocks\":";
    s += "[";
    for (size_t i = 0; i < event_blocks.size(); ++i) {
        if (i > 0) s += ",";
        s += event_blocks[i].to_json();
    }
    s += "]";
    s += ",";
    s += "\"footer_count\":";
    s += std::to_string(footer_count);
    s += ",";
    s += "\"footer_entries\":";
    s += "[";
    for (size_t i = 0; i < footer_entries.size(); ++i) {
        if (i > 0) s += ",";
        s += footer_entries[i].to_json();
    }
    s += "]";
    s += "}";
    return s;
}

std::vector<uint8_t> File::to_bytes() const {
    std::vector<uint8_t> _buf;
    {
        uint32_t _tmp = magic;
        uint8_t _raw[4];
        std::memcpy(_raw, &_tmp, 4);
        _buf.insert(_buf.end(), _raw, _raw + 4);
    }
    {
        auto _tmp = header.to_bytes();
        _buf.insert(_buf.end(), _tmp.begin(), _tmp.end());
    }
    {
        uint32_t _tmp = static_cast<uint32_t>(units.size());
        uint8_t _raw[4];
        std::memcpy(_raw, &_tmp, 4);
        _buf.insert(_buf.end(), _raw, _raw + 4);
    }
    for (const auto& _item : units) {
        auto _tmp = _item.to_bytes();
        _buf.insert(_buf.end(), _tmp.begin(), _tmp.end());
    }
    {
        uint32_t _tmp = static_cast<uint32_t>(areas.size());
        uint8_t _raw[4];
        std::memcpy(_raw, &_tmp, 4);
        _buf.insert(_buf.end(), _raw, _raw + 4);
    }
    for (const auto& _item : areas) {
        auto _tmp = _item.to_bytes();
        _buf.insert(_buf.end(), _tmp.begin(), _tmp.end());
    }
    {
        uint32_t _tmp = static_cast<uint32_t>(variables.size());
        uint8_t _raw[4];
        std::memcpy(_raw, &_tmp, 4);
        _buf.insert(_buf.end(), _raw, _raw + 4);
    }
    for (const auto& _item : variables) {
        auto _tmp = _item.to_bytes();
        _buf.insert(_buf.end(), _tmp.begin(), _tmp.end());
    }
    {
        uint32_t _tmp = static_cast<uint32_t>(event_blocks.size());
        uint8_t _raw[4];
        std::memcpy(_raw, &_tmp, 4);
        _buf.insert(_buf.end(), _raw, _raw + 4);
    }
    for (const auto& _item : event_blocks) {
        auto _tmp = _item.to_bytes();
        _buf.insert(_buf.end(), _tmp.begin(), _tmp.end());
    }
    {
        uint32_t _tmp = static_cast<uint32_t>(footer_entries.size());
        uint8_t _raw[4];
        std::memcpy(_raw, &_tmp, 4);
        _buf.insert(_buf.end(), _raw, _raw + 4);
    }
    for (const auto& _item : footer_entries) {
        auto _tmp = _item.to_bytes();
        _buf.insert(_buf.end(), _tmp.begin(), _tmp.end());
    }
    return _buf;
}

